export const JEDEC_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/jedec-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getJedecStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(JEDEC_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
